 publication_year,source_reference,checked_at,validation_method,validation_evidence,
 assumptions,missing_inputs,model_version,verified_results,unresolved_issues,next_action,details)
select i.title,i.category,i.horizon,i.status,i.value_text,i.unit,i.source_url,i.document_title,
